<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher,tick} from 'svelte';
 import {AddBotClient,type BotTemplate,type NewBot} from './add-bot-client';
 export let accessSignal:AbortSignal;
 export let companyId:string;export let companyName='your company';export let membershipRevision=0;
 let step=1;let panel:HTMLElement;
 const scratch={id:'__scratch__',version:1,name:'New bot',role:'',instructions:''};
 const shortTemplateName=(name:string)=>name.replace(/\s+the\s+.+$/i,'').trim();
 const dispatch=createEventDispatcher();let boundSignal:AbortSignal|undefined;let client:AddBotClient|null=null,ready=false,scope='',loading=true,busy=false,completed=false,canCreate=false,error='',templates:BotTemplate[]=[],templateId='',name='',purpose='',instructions='',uncertain=false;
 $: currentScope=JSON.stringify([companyId,membershipRevision]);$: if(ready&&currentScope!==scope){scope=currentScope;void load();}
 $: selected=templateId==='__scratch__'?scratch:templates.find(t=>t.id===templateId);
 async function customize(){if(!selected)return;step=2;await tick();panel?.scrollTo({top:0});panel?.querySelector<HTMLInputElement>('#new-bot-name')?.focus();}
 function parentRevoked(){client?.forgetSession();client=null;templates=[];canCreate=false;busy=false;completed=false;uncertain=false;loading=false;templateId='';name='';purpose='';instructions='';error='Company access changed. Reopen your workspace.';dispatch('accesschanged',{status:403});}
 $: if(ready&&boundSignal!==accessSignal){boundSignal?.removeEventListener('abort',parentRevoked);boundSignal=accessSignal;boundSignal?.addEventListener('abort',parentRevoked,{once:true});if(boundSignal?.aborted)parentRevoked();}
 async function load(){step=1;if(accessSignal?.aborted){parentRevoked();return;}client?.close();const current=client=new AddBotClient(companyId,()=>localStorage.token||'');loading=true;busy=false;completed=false;canCreate=false;templates=[];error='';templateId='';name='';purpose='';instructions='';uncertain=false;try{const [access,available]=await Promise.all([current.access(),current.templates()]);if(current!==client)return;canCreate=access.canCreate;templates=available;const prior=current.resume();if(prior){({templateId,name,purpose,instructions}=prior.draft);uncertain=true;step=2;}}catch(e){if(current===client)error=(e as Error).message;}finally{if(current===client)loading=false;}}
 function choose(t:BotTemplate){if(busy||uncertain)return;templateId=t.id;name=shortTemplateName(t.name);purpose=t.role||'';instructions=t.instructions;error='';}
 async function create(){if(!client||busy||completed||!canCreate||!selected||!name.trim())return;const current=client;busy=true;error='';const draft:NewBot={templateId,name:name.trim(),purpose,instructions};try{const result=await current.create(draft);if(current!==client)return;uncertain=false;completed=true;dispatch('created',result);}catch(e){if(current!==client)return;const status=(e as any).status;uncertain=!!current.resume();if([401,403].includes(status)){canCreate=false;name='';purpose='';instructions='';dispatch('accesschanged',{status});}error=(e as Error).message+(uncertain?' Creation is unconfirmed. Retry these same details to retrieve the original result.':'');}finally{if(current===client)busy=false;}}
 function session(e:StorageEvent){if(e.key==='token'||e.key===null){client?.forgetSession();client=null;templates=[];canCreate=false;name='';purpose='';instructions='';error='Your session changed. Reopen your company.';dispatch('accesschanged',{status:401});}}
 onMount(()=>{ready=true;window.addEventListener('storage',session);return()=>window.removeEventListener('storage',session);});onDestroy(()=>{client?.close();boundSignal?.removeEventListener('abort',parentRevoked);});
</script>

<section bind:this={panel} class="add-bot" aria-label="Add bot" aria-busy={loading||busy}>
 <button class="back" disabled={busy} on:click={()=>dispatch('close',{dirty:!!templateId,uncertain})}>← Your AI team</button>
 <p class="eyebrow">GROW YOUR TEAM</p><h1>Add a bot</h1><p class="intro">Start from scratch or choose a specialist for {companyName}.</p>
 {#if error}<div class="alert" role="alert">{error}</div>{/if}
 {#if loading}<p class="loading" role="status">Loading company access and bot templates…</p>
 {:else if error&&!templates.length}<div class="empty"><h2>Bot setup is unavailable</h2><p>Reload to check company access and the template service.</p><button class="secondary" on:click={load}>Reload setup</button></div>{:else if !canCreate}<div class="empty"><h2>Company admin access required</h2><p>Only company owners and admins can add bots to this team.</p><button class="secondary" on:click={load}>Check access again</button></div>
 {:else}{#if step===1}<h2 class="step">01 <span>Choose a starting point</span></h2><div class="templates"><button class="template scratch" class:selected={templateId==='__scratch__'} disabled={busy||uncertain} on:click={()=>{choose(scratch);name='';}} aria-pressed={templateId==='__scratch__'}><span class="avatar">＋</span><span class="template-copy"><strong>Start from scratch</strong><small>Your own name, role and instructions</small></span><span class="radio">{templateId==='__scratch__'?'✓':''}</span><p>Create a blank bot and define exactly how it should help.</p></button>{#each templates as t}<button class="template" class:selected={templateId===t.id} disabled={busy||uncertain} on:click={()=>choose(t)} aria-pressed={templateId===t.id}><span class="avatar">{shortTemplateName(t.name).slice(0,1)}</span><span class="template-copy"><strong>{shortTemplateName(t.name)}</strong><small>{t.role||'Company agent'}</small></span><span class="radio">{templateId===t.id?'✓':''}</span>{#if t.personality}<p>{t.personality}</p>{/if}</button>{/each}</div>
 <div class="next-bar"><span>{selected?(templateId==='__scratch__'?'Blank bot selected':shortTemplateName(selected.name)+' selected'):'Choose a starting point'}</span><button class="primary" type="button" disabled={!selected} on:click={customize}>Next: Customize <span aria-hidden="true">→</span></button></div>{/if}
 {#if step===2&&selected}<button class="change-template" type="button" disabled={busy||uncertain} on:click={()=>step=1}>← Change starting point</button><form on:submit|preventDefault={create}><h2 class="step">02 <span>Make it your own</span></h2><label for="new-bot-name">Bot name</label><input id="new-bot-name" bind:value={name} maxlength="100" required disabled={busy||uncertain}/><label for="new-bot-purpose">Purpose</label><textarea id="new-bot-purpose" bind:value={purpose} maxlength="2000" rows="2" disabled={busy||uncertain}/><label for="new-bot-instructions">Instructions</label><p class="hint">Tell this bot how to help your team. You can refine these settings later.</p><textarea id="new-bot-instructions" class="instructions" bind:value={instructions} maxlength="16000" rows="7" disabled={busy||uncertain}/><div class="note"><span>↗</span><p>Your bot starts with empty memory. Choose a provider and assign permissions in settings before it can work.</p></div><footer><span>Added to {companyName}</span><button class="primary" disabled={busy||completed||!name.trim()}>{completed?'Bot added':busy?'Adding bot…':uncertain?'Retry original creation':'Add bot to team'} <span>→</span></button></footer></form>{/if}{/if}
</section>

<style>
 .add-bot{max-width:1000px;margin:0 auto;padding:35px 45px 55px;color:#17243F}.back{background:none;border:0;padding:0;color:#71809A;font-size:13px;cursor:pointer}.eyebrow{margin:35px 0 12px;color:#3466F6;font-size:10px;font-weight:600;letter-spacing:2px}h1{font-size:27px;line-height:1.2;letter-spacing:-.7px;font-weight:500;margin:0}.intro{max-width:520px;color:#71809A;font-size:13px;line-height:1.8;margin:17px 0 32px}.step{display:flex;gap:12px;color:#71809A;font-size:11px;font-weight:400;margin:28px 0 17px}.step span{font-size:15px;color:#17243F;font-weight:500}.templates{display:grid;grid-template-columns:1fr 1fr;gap:12px}.template{background:#FFFFFF;border:1px solid #E6EBF4;border-radius:12px;display:flex;align-items:center;gap:13px;flex-wrap:wrap;padding:19px;text-align:left;color:inherit;cursor:pointer}.template:hover{border-color:#AFC2FA}.template.selected{border-color:#3466F6;background:#EEF3FF}.avatar{width:42px;height:42px;display:grid;place-items:center;border-radius:13px;background:#EAF0FF;color:#3466F6;font-size:18px}.template-copy{display:flex;flex-direction:column;gap:5px;flex:1}.template strong{font-size:14px;font-weight:500}.template small{font-size:11px;color:#71809A}.template p{width:100%;font-size:11px;color:#71809A;line-height:1.7;margin:0}.radio{height:17px;width:17px;border:1px solid #C7D2E5;border-radius:50%;display:grid;place-items:center;font-size:10px}.selected .radio{background:#3466F6;border-color:#3466F6;color:#FFFFFF}form{max-width:720px;margin-top:33px}label{display:block;margin:21px 0 10px;font-size:12px;color:#17243F}input,textarea{box-sizing:border-box;width:100%;background:#FFFFFF;border:1px solid #E6EBF4;border-radius:9px;padding:12px 14px;font:inherit;font-size:13px;color:#17243F;outline:none}textarea{resize:vertical;line-height:1.75}input:focus,textarea:focus{border-color:#3466F6}.instructions{font-family:ui-monospace,Consolas,monospace;font-size:12px}.hint{font-size:11px;color:#71809A;line-height:1.7;margin:0 0 12px}.note{display:flex;align-items:center;gap:12px;border:1px solid #E6EBF4;border-radius:9px;padding:12px 15px;margin-top:20px}.note>span{color:#3466F6}.note p{margin:0;font-size:11px;line-height:1.7;color:#71809A}footer{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-top:25px;padding-top:23px;border-top:1px solid #E6EBF4}footer>span{font-size:11px;color:#71809A}.primary,.secondary{border:0;border-radius:8px;font-size:12px;padding:11px 18px;cursor:pointer}.primary{background:#3466F6;color:#FFFFFF;font-weight:600;display:flex;gap:20px;align-items:center}.secondary{background:#F6F8FC;color:#17243F;margin-top:15px}button:disabled,input:disabled,textarea:disabled{opacity:.55;cursor:default}.alert{padding:13px 15px;background:#FFF4F4;border:1px solid #F3D2D5;border-radius:9px;color:#A62D35;font-size:12px;line-height:1.7;margin:20px 0}.empty{padding:25px 0;color:#71809A;font-size:13px}.empty h2{font-size:17px;color:#17243F}.loading{padding:20px 0;color:#71809A;font-size:13px}button:focus-visible{outline:2px solid #3466F6;outline-offset:4px}@media(max-width:650px){.add-bot{padding:25px 20px}.templates{grid-template-columns:1fr}h1{font-size:30px}footer{align-items:flex-start;flex-direction:column}}
.add-bot{width:100%;height:100%;min-height:0;overflow:auto}.next-bar{position:sticky;bottom:0;margin:24px -8px -30px;padding:18px 8px 22px;display:flex;justify-content:space-between;align-items:center;gap:16px;background:linear-gradient(#ffffffeb,#fff 30%);border-top:1px solid #e6ebf4;z-index:2}.next-bar>span{font-size:12px;color:#71809a}.change-template{margin-top:10px;border:0;background:none;color:#71809a;font:inherit;font-size:12px;padding:0;cursor:pointer}.scratch{border-style:dashed}.scratch.selected{border-style:solid}@media(max-width:650px){.next-bar{bottom:0;margin-bottom:-10px}.next-bar .primary{white-space:nowrap;padding:11px 12px;gap:8px}}
</style>



